conflicting_evidence.evidence:
{
  "code": "from flask import request

@app.route('/search')
def search():
    query = request.args.get('q', '')
    return '<h1>Search results for: ' + query + '</h1>'",
  "explanation": "The application directly concatenates user-controlled data into an HTML response without appropriate output encoding."
}

{
  "code": "from flask import Flask, request
from markupsafe import Markup

app = Flask(__name__)

@app.route('/hello')
def hello():
    name = request.args.get('name', '')
    return Markup('<h1>Hello ' + name + '</h1>')",
  "explanation": "User-controlled input is inserted into HTML and explicitly marked as safe, which can allow malicious HTML or script content to be interpreted by the browser."
}

{
  "code": "import os\nDB_PASSWORD = os.environ.get('DB_PASSWORD')",
  "explanation": "The database password is obtained from an environment variable instead of being embedded directly in source code."
}

{
  "code": "connection = connect(host=\"db.example.com\", user=\"admin\", password=\"admin123\")",
  "explanation": "Database credentials are hard-coded directly into the application source."
}

{
  "code": "import os\ncommand = \"ping \" + hostname\nos.system(command)",
  "explanation": "User-controlled hostname data is concatenated into a shell command before execution."
}

{
  "code": "import subprocess\nsubprocess.run(user_input, shell=True)",
  "explanation": "The command is interpreted by a shell while containing user-controlled input, creating a command injection risk."
}

{
  "code": "import os\nos.system(user_input)",
  "explanation": "The user-controlled input is passed directly to os.system(), allowing the input to influence the operating system command."
}

